module castle_danger (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] p0_x, p0_y,\n    input wire [7:0] p1_x, p1_y,\n    input wire [7:0] p2_x, p2_y,\n    input wire [7:0] p3_x, p3_y,\n    input wire [7:0] castle_x, castle_y,\n    output reg danger,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE      = 2'd0;\n    localparam [1:0] CHECK     = 2'd1;\n    localparam [1:0] CHECK_SGN = 2'd2;\n    localparam [1:0] DONE_ST   = 2'd3;\n    \n    reg [1:0] state;\n    reg [1:0] edge_idx;\n    reg [15:0] cross;\n    reg is_inside;\n    reg first_sign;\n    reg degenerate;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            danger <= 1'b0;\n            done <= 1'b0;\n            is_inside <= 1'b0;\n            degenerate <= 1'b0;\n            edge_idx <= 2'd0;\n            cross <= 16'd0;\n            first_sign <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    danger <= 1'b0;\n                    if (start) begin\n                        state <= CHECK;\n                        edge_idx <= 2'd0;\n                        is_inside <= 1'b1;\n                        degenerate <= 1'b0;\n                    end\n                end\n\n                CHECK: begin\n                    // Compute cross product\n                    case (edge_idx)\n                        2'd0: cross <= ((p1_x - p0_x) * (castle_y - p0_y)) - ((p1_y - p0_y) * (castle_x - p0_x));\n                        2'd1: cross <= ((p2_x - p1_x) * (castle_y - p1_y)) - ((p2_y - p1_y) * (castle_x - p1_x));\n                        2'd2: cross <= ((p3_x - p2_x) * (castle_y - p2_y)) - ((p3_y - p2_y) * (castle_x - p2_x));\n                        2'd3: cross <= ((p0_x - p3_x) * (castle_y - p3_y)) - ((p0_y - p3_y) * (castle_x - p3_x));\n                    endcase\n                    state <= CHECK_SGN;\n                end\n\n                CHECK_SGN: begin\n                    if (edge_idx == 2'd0) begin\n                        // Check base case for degeneracy\n                        if ((((p1_x - p0_x) * (p2_y - p0_y)) - ((p1_y - p0_y) * (p2_x - p0_x)) == 16'd0) ||\n                            (((p2_x - p1_x) * (p3_y - p1_y)) - ((p2_y - p1_y) * (p3_x - p1_x)) == 16'd0) ||\n                            (((p3_x - p2_x) * (p0_y - p2_y)) - ((p3_y - p2_y) * (p0_x - p2_x)) == 16'd0) ||\n                            (((p0_x - p3_x) * (p1_y - p3_y)) - ((p0_y - p3_y) * (p1_x - p3_x)) == 16'd0)) begin\n                            degenerate <= 1'b1;\n                        end\n                        if (cross != 16'd0) first_sign <= cross[15];\n                    end else begin\n                        // Check sign consistency\n                        if ((cross != 16'd0) && (cross[15] != first_sign)) begin\n                            is_inside <= 1'b0;\n                        end\n                    end\n\n                    if (edge_idx < 2'd3) begin\n                        edge_idx <= edge_idx + 2'd1;\n                        state <= CHECK;\n                    end else begin\n                        state <= DONE_ST;\n                    end\n                end\n\n                DONE_ST: begin\n                    danger <= degenerate ? 1'b0 : is_inside;\n                    done <= 1'b1;\n                    if (!start) state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule